document.addEventListener('click', e => { const t = e.target; if (t.closest('a')) return; const rr = t.closest('[data-rule]'); if (rr) { openRule(rr.dataset.rule); return; } const mm = t.closest('[data-metric]'); if (mm && !t.closest('.chart-card')) { openMetric(mm.dataset.metric); return; } const nd = t.closest('.node[data-chain]'); if (nd) { const step = CHAINS[nd.dataset.chain].steps[+nd.dataset.step]; const ns = nodeState(step); openDrawer({ head: `<div class="chips"><span class="chip">${esc(CHAINS[nd.dataset.chain].title)}</span></div><h3 style="margin-top:6px">0${+nd.dataset.step + 1} ${esc(step.name)}</h3>`, body: `<div class="sec"><div class="k">报告论证</div><div>${esc(step.claim)}</div></div><div class="sec"><div class="k">今日读数</div>${(step.metrics || []).map(k => `<div class="rrow" data-metric="${esc(k)}" style="grid-template-columns:1fr auto;padding:6px 0"><span>${esc(labelOf(k))}</span><span class="mono">${fmtMetric(k, v(k))}</span></div>`).join('')}</div><div class="sec"><div class="k">对应规则 ${ns.satisfied}/${ns.total} 触发</div>${ns.rules.map(r => `<div class="rrow" data-rule="${esc(r.rule_id)}" style="grid-template-columns:1fr;padding:6px 0"><div>${stateChip(r)} ${esc(r.title)}</div><div class="why">${r._p.text || esc(r.why)}</div></div>`).join('')}</div>` }); return; } const gh = t.closest('.group .gh'); if (gh) { const g = gh.closest('.group'); g.dataset.open = g.dataset.open === 'true' ? 'false' : 'true'; gh.querySelector('.n:last-child').textContent = g.dataset.open === 'true' ? '收起' : '展开'; } });
document.addEventListener('keydown', e => { if (e.key === 'Escape') { closeDrawer(); document.querySelectorAll('.pop,.sheet').forEach(p => p.dataset.open = 'false'); } if (e.key === 'Enter' && e.target.matches('[role=button]')) e.target.click(); if (/^[1-7]$/.test(e.key) && !e.target.matches('input,select,textarea')) show(['overview', 'crypto', 'geo', 'ai', 'track', 'read', 'data'][+e.key - 1]); });

// ---------- pages ----------
const REPORT_TOPICS = rep => Object.entries(TOPICS).filter(([k, t]) => t.report === rep).map(([k]) => k);
function keyJudgements(rep, thesis) { const sents = String(thesis || '').split(/(?<=[。；])/).filter(s => s.trim()).slice(0, 3); const top = byReport(rep).filter(r => r.fired).sort(radarSort).slice(0, 3); return `<div class="card"><div class="kicker">关键判断</div><ul style="margin:8px 0 0;padding-left:18px">${sents.map(s => `<li>${esc(s.trim())}</li>`).join('')}${top.map(r => `<li>${lvlChip(r.level)} <a href="#rule=${esc(r.rule_id)}" data-rule="${esc(r.rule_id)}" onclick="return false">${esc(r.title)}</a> <span class="mono small">${r._p.text}</span></li>`).join('')}</ul></div>`; }
function sectionRules(rep) { const rows = byReport(rep); const f = rows.filter(r => r.fired).length; const nr = rows.filter(r => r._near).length; return `<h2>条件仪表盘 <span class="count">${rows.length} 条</span><span class="take">${f} 触发 · ${nr} 接近阈值 · ${rows.filter(r => r.status === 'nodata').length} 无数据</span></h2>${ruleGroups(rows)}`; }
function sectionNews(rep, n) { const set = new Set(REPORT_TOPICS(rep)); const cs = clusters(x => (x.topics || []).some(t => set.has(t))).slice(0, n || 6); return `<h2>相关新闻 <span class="count">${cs.length} 条线索</span><span class="right"><a href="#read" data-goto="read">阅读 →</a></span></h2><div class="card">${cs.length ? cs.map(c => storyline(c, 4)).join('') : '<div class="empty">近 7 天无相关新闻</div>'}</div>`; }
function sectionCal(rep) { const rows = CAL.filter(e => e.report === rep && e.days_to >= -1); return `<h2>触发日历 <span class="count">${rows.length} 项</span></h2><div class="card">${calRows(e => e.report === rep)}</div>`; }

function renderOverview() {
  const el = document.getElementById('tab-overview'); const run = D.run || {};
  const newR = fired.filter(r => r.is_new); const chg = newR.length + resolved.length;
  const cnt = { opportunity: 0, warning: 0, invalidation: 0, event: 0, info: 0 }; newR.forEach(r => cnt[r.level]++);
  const verdict = chg ? `${chg} 条规则变化：${newR.length} 新触发（机会 ${cnt.opportunity}、风险 ${cnt.warning}、失效 ${cnt.invalidation}、事件 ${cnt.event}）、${resolved.length} 解除。` : `无新触发，维持 ${YDAY || TODAY} 的判断。`;
  const why = [...fired].sort((a, b) => b._score - a._score || a.priority - b.priority).slice(0, 3);
  const diffRows = [...newR.map(r => ({ g: '▲', w: '新触发', r })), ...resolved.map(r => ({ g: '▼', w: '解除', r })), ...nearRules.slice(0, 3).map(r => ({ g: '●', w: '接近阈值', r }))].slice(0, 7);
  const next14 = CAL.filter(e => e.days_to >= 0 && e.days_to <= 14).slice(0, 5);
  const big = ['crypto', 'war', 'ai'].map(k => { const s = chainSummary(k); return s ? `<div class="line"><a href="#${k === 'war' ? 'geo' : k}" data-goto="${k === 'war' ? 'geo' : k}">${esc(CHAINS[k].title.split('：')[0])}</a>：${s.k}/${s.m} 节点触发 · 变化：${s.changed.length ? s.changed.map(esc).join('、') : '无'}</div>` : ''; }).join('');
  const cjk = (verdict + why.map(r => r.title + r.action).join('')).length; const mins = Math.max(1, Math.ceil(cjk / 400));
  let h = '';
  if (lastVisit && chg) h += `<div class="banner">自 ${esc(new Date(lastVisit).toLocaleString('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }))} 以来：新触发 ${newR.length} · 解除 ${resolved.length}<span class="x muted small">规则卡左上角的点表示上次访问后新触发</span></div>`;
  h += `<h2 style="margin-top:20px">今日简报 <span class="count">${new Date(TODAY).toLocaleDateString('zh-CN', { weekday: 'long' })}</span><span class="take muted">约 ${mins} 分钟 · ${RULES.length} 条规则已评估</span></h2><div class="card brief">`;
  h += `<div><div class="kicker">一句话结论</div><div class="verdict">${esc(verdict)}</div><div class="pills">${[['触发', fired.length, 'fired'], ['接近', nearRules.length, 'near'], ['未触发', RULES.filter(r => r.status === 'idle' && !r._near).length, 'idle'], ['无数据', RULES.filter(r => r.status === 'nodata').length, 'nodata'], ['已解除', resolved.length, 'resolved']].map(p => `<span class="pill" data-filter="${p[2]}"><b>${p[1]}</b><span>${p[0]}</span></span>`).join('')}</div>`;
  h += `<div class="kicker">为什么重要</div><ul class="why">${why.length ? why.map(r => `<li>${lvlChip(r.level)}<span><b>${esc(r.title)}</b>：<span class="mono">${r._p.text}</span> → ${esc(String(r.action || '').split(/[；;（(]/)[0].slice(0, 24))}</span></li>`).join('') : '<li class="muted">今日无高优先级变化。</li>'}</ul>`;
  h += `<div class="kicker">变化了什么</div>${diffRows.length ? `<div class="diffwrap"><table class="diff"><thead><tr><th>状态</th><th>规则</th><th>读数</th><th>依据</th></tr></thead><tbody>${diffRows.map(x => `<tr data-rule="${esc(x.r.rule_id)}" style="cursor:pointer"><td><b>${x.g}</b> ${x.w}</td><td>${lvlChip(x.r.level)} ${esc(x.r.title)}</td><td class="mono small">${x.r._p ? x.r._p.text : ''}</td><td class="small muted">${repChip(x.r.report)} ${esc(String(x.r.source || '').slice(0, 18))}</td></tr>`).join('')}</tbody></table></div>` : '<div class="muted small">无变化 · 数据已更新</div>'}</div>`;
  h += `<div class="side"><div class="kicker">大局</div>${big}<div class="kicker" style="margin-top:12px">接下来 14 天</div>${next14.length ? next14.map(e => `<div class="line"><span class="mono">${e.days_to === 0 ? '今天' : e.days_to + ' 天后'}</span> · ${esc(e.title)} ${assetChips(e.assets, 2)} ${repChip(e.report)}</div>`).join('') : '<div class="muted small">14 天内无催化剂</div>'}</div>`;
  h += `<div class="deep">深入：<a href="#track" data-goto="track">推演追踪（${prevDates.length + 1} 天日志）</a> · <a href="#read" data-goto="read">阅读（${NEWS.length} 条 · 3 份报告）</a> · <a href="#data" data-goto="data">数据（${Object.values(run.fetchers || {}).filter(f => f.ok === true).length}/${Object.values(run.fetchers || {}).filter(f => !f.skipped).length} 抓取器正常）</a></div></div>`;
  // KPI
  const kAll = LS('kpi_all') === '1';
  const tiles5 = [tile({ label: 'BTC', key: 'px.BTC', delta: 'chg24h.BTC', deltaLabel: '24h', spark: 'px.BTC', prefix: '$', hero: true, sub: `较 ATH ${fmtPct(v('athdd.BTC'))} · 50周线 ${fmtPx(v('crypto.btc.wma50'))}` }), tile({ label: 'ETH/BTC', key: 'crypto.ethbtc', fmt: 'num', d: 4, spark: 'crypto.ethbtc', sub: '加仓区 .028–.030 · 失效 <.025' }), tile({ label: '布伦特（期货）', key: 'px.BRENT', delta: 'chg1d.BRENT', spark: 'px.BRENT', prefix: '$', sub: `战前 $72.5 · 现货溢价 $${fmtNum(v('war.brent_physical_premium'), 0)}` }), tile({ label: '黄金', key: 'px.GOLD', delta: 'chg1d.GOLD', spark: 'px.GOLD', prefix: '$', sub: `较 ATH ${fmtPct(v('dd_ath.GOLD'))}（报告 ${MINUS}22%）` }), tile({ label: '10 年期美债', key: 'px.US10Y', fmt: 'num', d: 2, unit: '%', spark: 'px.US10Y', sub: '>5% 逆风 · <4% 顺风' })];
  const tilesMore = [tile({ label: 'VIX', key: 'px.VIX', fmt: 'num', d: 1, spark: 'px.VIX', sub: '>30 = 历史买点窗口' }), tile({ label: '美元指数', key: 'px.DXY', fmt: 'num', d: 2, delta: 'chg30d.DXY', deltaLabel: '30d', spark: 'px.DXY' }), tile({ label: '标普 500', key: 'px.SPX', delta: 'chg1d.SPX', spark: 'px.SPX', sub: `YTD ${fmtPct(v('ytd.SPX'))}` }), tile({ label: '英伟达', key: 'px.NVDA', delta: 'chg1d.NVDA', spark: 'px.NVDA', prefix: '$', sub: `较52周高 ${fmtPct(v('dd52w.NVDA'))}` }), tile({ label: 'KOSPI', key: 'px.KOSPI', delta: 'chg1d.KOSPI', spark: 'px.KOSPI', sub: `较52周高 ${fmtPct(v('dd52w.KOSPI'))}` }), tile({ label: '台股', key: 'px.TAIEX', delta: 'chg1d.TAIEX', spark: 'px.TAIEX', sub: `较52周高 ${fmtPct(v('dd52w.TAIEX'))}` }), tile({ label: '莱茵金属', key: 'px.RHM', delta: 'chg1d.RHM', spark: 'px.RHM', prefix: '€', sub: `较高点 ${fmtPct(v('dd_ath.RHM'))}` }), tile({ label: '稳定币总量', key: 'stable.total', spark: 'stable.total', prefix: '$' }), tile({ label: '恐惧贪婪', key: 'crypto.fng', fmt: 'num', d: 0, spark: 'crypto.fng', sub: meta('crypto.fng').label || '' }), tile({ label: '霍尔木兹通行/基线', key: 'chokepoint.hormuz.ratio', fmt: 'pct', spark: 'chokepoint.hormuz.transits', sub: `7日均 ${fmtNum(v('chokepoint.hormuz.avg7'), 1)} 艘/日` }), tile({ label: 'Kalshi 10月加息', key: 'kalshi.fed_next.hike', fmt: 'num', d: 0, unit: '%', sub: '替代 CME FedWatch' })];
  h += `<h2>今日读数 <span class="count">${kAll ? 16 : 5} / 16</span><span class="right"><button class="pillbtn" id="kpi-toggle" aria-pressed="${kAll}">${kAll ? '只看 5 个' : '全部 16'}</button></span></h2><div class="grid g-kpi" id="kpi-grid">${tiles5.join('')}${kAll ? tilesMore.join('') : ''}</div>`;
  // radar
  const sorted = [...RULES].filter(r => r.fired || r._near).sort(radarSort); const top = sorted.slice(0, 5);
  h += `<h2>机会雷达 <span class="count">${fired.length}/${RULES.length} 触发</span><span class="take">新触发 ${newR.length} · 接近阈值 ${nearRules.length}</span><span class="right muted">排序：状态 › 级别 › 距阈值</span></h2>`;
  h += top.length ? `<div class="rlist">${top.map(r => ruleCard(r)).join('')}</div>` : `<div class="card empty">当前无触发条件</div>`;
  const rest = sorted.length - top.length; if (rest > 0) { const byRep = {}; sorted.slice(5).forEach(r => byRep[r.report] = (byRep[r.report] || 0) + 1); h += `<div class="small muted" style="margin-top:8px">另有 ${rest} 条：${Object.entries(byRep).map(([k, n]) => `<a href="#${k === 'war' ? 'geo' : (k === 'all' ? 'geo' : k)}" data-goto="${k === 'war' ? 'geo' : (k === 'all' ? 'geo' : k)}">${esc(rl(k))} ${n}</a>`).join(' · ')}</div>`; }
  h += `<h2>三条主线的位置 <span class="count">相对报告基准日 2026-09-20</span></h2><div class="grid g-3">${['crypto', 'war', 'ai'].map(k => `<div class="card" style="padding:12px"><div style="display:flex;justify-content:space-between;align-items:baseline"><b>${esc(CHAINS[k] ? CHAINS[k].title : k)}</b><a href="#${k === 'war' ? 'geo' : k}" data-goto="${k === 'war' ? 'geo' : k}" class="small">打开 →</a></div>${stepper(k, 'compact').replace('class="stepper compact"', 'class="stepper compact vertical"')}</div>`).join('')}</div>`;
  const next45 = CAL.filter(e => e.days_to >= 0 && e.days_to <= 45);
  h += `<h2>接下来 45 天 <span class="count">${next45.length} 项</span></h2><div class="card"><div id="cal5">${calRows(e => e.days_to >= 0 && e.days_to <= 45, 5)}</div>${next45.length > 5 ? `<details><summary class="small muted" style="cursor:pointer;padding:8px 0">全部 ${next45.length} 项 · 45 天</summary>${calRows(e => e.days_to >= 0 && e.days_to <= 45).split('</div>').slice(5).join('</div>')}</details>` : ''}</div>`;
  const cs = clusters().slice(0, 5);
  h += `<h2>今日要闻 <span class="count">${cs.length} 条线索</span><span class="right"><a href="#read" data-goto="read">阅读 → 全部 ${NEWS.length} 条</a></span></h2><div class="card">${cs.map(c => storyline(c, 3)).join('')}</div>`;
  // 专业模式也有「怎么算」：页脚链接两种模式都有落点
  h += `<details class="appendix" id="method"><summary>怎么算（1 分钟）</summary><div class="body method">${METHOD_HTML}</div></details>`;
  el.innerHTML = h;
  document.getElementById('kpi-toggle').addEventListener('click', () => { LS('kpi_all', kAll ? '0' : '1'); rendered.overview = false; renderOverview(); });
}

function renderReport(tab) {
  const rep = { crypto: 'crypto', geo: 'war', ai: 'ai' }[tab]; const el = document.getElementById('tab-' + tab); const rp = (D.reports || []).find(r => r.id === rep) || {};
  let h = `<h2 style="margin-top:20px">${esc(rp.title || '')} <span class="count">${esc(rp.window || '')}</span></h2>` + keyJudgements(rep, rp.thesis);
  const cs = chainSummary(rep);
  h += `<h2>逻辑链实况 <span class="count">${cs ? cs.k + '/' + cs.m + ' 节点触发' : ''}</span><span class="take">${cs && cs.changed.length ? '较昨日变化：' + cs.changed.map(esc).join('、') : '较昨日无节点变化'}</span></h2>${stepper(rep)}`;
  h += sectionRules(rep);
  if (tab === 'crypto') {
    const btc = v('px.BTC'), w50 = v('crypto.btc.wma50'), w200 = v('crypto.btc.wma200'), rp_ = v('crypto.btc.realized_price'); const lo = Math.min(btc, w200, rp_, 53600) * 0.95, hi = Math.max(btc, w50, 126198) * 1.02; const pos = x => ((x - lo) / (hi - lo) * 100).toFixed(1);
    h += `<h2>周期位置 <span class="take">BTC ${fmtPx(btc)} · 50周线 ${fmtPx(w50)} · 200周线 ${fmtPx(w200)} · 实现价格 ${fmtPx(rp_)}</span></h2><div class="card"><div style="position:relative;height:56px;margin:8px 12px 0">${[[53600, '$53.6K 失效'], [rp_, '实现价格'], [w200, '200周'], [w50, '50周'], [126198, 'ATH']].map(([x, l], i) => x ? `<div style="position:absolute;left:${pos(x)}%;top:0;bottom:16px;border-left:${i === 0 ? '2px solid var(--st-invalidation)' : '1px solid var(--axis)'}"></div><div style="position:absolute;left:${pos(x)}%;bottom:0;transform:translateX(-50%);font:400 11px/16px var(--font-mono);color:var(--muted);white-space:nowrap">${esc(l)}</div>` : '').join('')}<div style="position:absolute;left:0;right:0;top:20px;height:6px;background:var(--surface-3);border-radius:3px"></div><div style="position:absolute;left:${pos(btc)}%;top:14px;width:18px;height:18px;border-radius:50%;background:var(--c1);transform:translateX(-50%);border:2px solid var(--surface)" title="BTC ${fmtPx(btc)}"></div></div><div class="grid g-kpi" style="margin-top:12px">${tile({ label: 'BTC 主导率', key: 'crypto.btc_dominance', fmt: 'num', d: 1, unit: '%', spark: 'crypto.btc_dominance', sub: '报告 58–60%；<55% 轮动' })}${tile({ label: '山寨季指数', key: 'crypto.altseason', fmt: 'num', d: 0, spark: 'crypto.altseason', sub: '>75 卫星止盈' })}${tile({ label: '恐惧贪婪', key: 'crypto.fng', fmt: 'num', d: 0, spark: 'crypto.fng', sub: meta('crypto.fng').label || '' })}${tile({ label: 'ETF 连续净流入', key: 'etf.btc.streak_days', fmt: 'num', d: 0, unit: '日', sub: `30日净流 $${fmtPx(v('etf.btc.flow_30d'))}` })}${tile({ label: 'BTC 资金费率', key: 'funding.BTC', fmt: 'num', d: 4, unit: '%/8h', sub: '>0.05 过热' })}${tile({ label: '距减半', key: 'btc.days_to_halving', fmt: 'num', d: 0, unit: '天', sub: '2028-04 · 峰值模板 2029' })}</div></div>`;
    const tiers = ['核心', '卫星', '期权', '期权（仅已持有）', '观察', '回避', '对照'];
    h += `<h2>43 标的 · 五档 <span class="count">${CRW.length} 行</span><span class="take">价格 CoinGecko · 费用/TVL DefiLlama · 评分来自报告</span></h2><div class="tbl"><table><thead><tr><th class="first">标的</th><th>档位</th><th class="num">价格</th><th class="num">24h</th><th class="num pri2">7d</th><th class="num">30d</th><th class="num pri3">1y</th><th class="num">较ATH</th><th class="num pri2">市值</th><th class="num pri3">FDV</th><th class="num pri3">30d费用</th><th class="num pri3">P/F</th><th class="num pri3">评分</th></tr></thead><tbody>${tiers.map(t => { const rows = CRW.filter(c => c.tier === t); return rows.length ? `<tr class="grp"><td class="first" colspan="13">${esc(t)} · ${rows.length}</td></tr>` + rows.map(c => { const s = c.symbol; return `<tr data-metric="px.${esc(s)}"><td class="first"><b>${esc(s)}</b><span class="ticker">${esc(meta('px.' + s).name || c.track || '')}</span></td><td class="small">${esc(t)}</td><td class="num">${fmtPx(v('px.' + s))}</td><td class="num">${dirHtml(v('chg24h.' + s))}</td><td class="num pri2">${dirHtml(v('chg7d.' + s))}</td><td class="num">${dirHtml(v('chg30d.' + s))}</td><td class="num pri3">${dirHtml(v('chg1y.' + s))}</td><td class="num">${dirHtml(v('athdd.' + s), 0)}</td><td class="num pri2">${fmtPx(v('mcap.' + s))}</td><td class="num pri3">${fmtPx(v('fdv.' + s))}</td><td class="num pri3">${fmtPx(v('fees30d.' + s))}</td><td class="num pri3">${v('pf.' + s) ? fmtNum(v('pf.' + s), 0) + 'x' : '—'}</td><td class="num pri3 small">${c.risk != null ? c.risk.toFixed(2) + ' / ' + c.elastic.toFixed(2) : ''}</td></tr>`; }).join('') : ''; }).join('')}</tbody></table></div>`;
    const un = Object.keys(M).filter(k => k.startsWith('unlock.next_days.')).map(k => ({ sym: k.split('.').pop(), m: M[k] })).sort((a, b) => (a.m.value == null ? 999 : a.m.value) - (b.m.value == null ? 999 : b.m.value));
    if (un.length) h += `<h2>解锁 <span class="count">DefiLlama</span><span class="take">报告规则：解锁悬崖前不持仓</span></h2><div class="tbl"><table><thead><tr><th class="first">标的</th><th class="num">下次解锁</th><th>说明</th></tr></thead><tbody>${un.map(u => { const nx = (u.m.meta || {}).next; return `<tr><td class="first"><b>${esc(u.sym)}</b></td><td class="num">${nx ? esc(nx.date) + '（' + Math.ceil(u.m.value) + ' 天后）' : '<span class="muted">未列</span>'}</td><td class="small muted">${nx ? esc(nx.type || '') + (nx.pct_circ ? ' · 约 ' + nx.pct_circ.toFixed(1) + '% 流通' : '') : ''}</td></tr>`; }).join('')}</tbody></table></div>`;
    h += `<h2>预测市场 <span class="count">Polymarket · Kalshi</span></h2><div class="grid g-prob">${['btc_100k', 'clarity_act', 'fed_next_hike', 'us_recession', 'anthropic_ipo'].map(probCard).join('')}</div>`;
    h += `<h2>走势</h2><div class="grid g-2">${chartCard({ id: 'c-btc', series: [{ key: 'px.BTC', role: 'focal' }, { key: 'crypto.btc.wma50', label: '50周', role: 'context' }, { key: 'crypto.btc.wma200', label: '200周', role: 'context' }], thresholds: [{ value: 53600, label: '$53.6K 失效', color: cssVar('--st-invalidation') }, { value: 126198, label: 'ATH' }], desc: 'BTC 现价与 50/200 周均线；$53.6K 为报告整体失效线', yFmt: x => '$' + fmtPx(x) })}${chartCard({ id: 'c-ethbtc', series: [{ key: 'crypto.ethbtc', role: 'focal' }], thresholds: [{ value: 0.028, label: '0.028' }, { value: 0.030, label: '0.030' }, { value: 0.025, label: '0.025 失效', color: cssVar('--st-invalidation') }], desc: 'ETH/BTC；加仓区 0.028–0.030', yFmt: x => x.toFixed(4) })}${chartCard({ id: 'c-stable', series: [{ key: 'stable.total', role: 'focal' }], area: true, desc: '稳定币总供给（DefiLlama）', yFmt: x => '$' + fmtPx(x) })}${chartCard({ id: 'c-usde', series: [{ key: 'stable.USDe', role: 'focal' }], thresholds: [{ value: 7.5e9, label: '$75亿 触发' }, { value: 4e9, label: '$40亿 失效', color: cssVar('--st-invalidation') }], desc: 'USDe 供给', yFmt: x => '$' + fmtPx(x) })}${chartCard({ id: 'c-fees', series: [{ key: 'fees30d.HYPE', role: 'focal' }, { key: 'fees30d.AAVE' }, { key: 'fees30d.UNI' }], desc: '30 日滚动手续费（美元）', yFmt: x => '$' + fmtPx(x) })}${chartCard({ id: 'c-chainrev', series: [{ key: 'chainrev30d.solana', label: 'Solana', role: 'focal' }, { key: 'chainrev30d.ethereum', label: 'Ethereum' }], desc: '链级 30 日收入（REV 近似）', yFmt: x => '$' + fmtPx(x) })}${chartCard({ id: 'c-etf', series: [{ key: 'etf.btc.flow_daily', label: 'BTC ETF 日净流', role: 'focal' }], desc: '美国现货 BTC ETF 每日净流入（SoSoValue）', yFmt: x => '$' + fmtPx(x) })}${chartCard({ id: 'c-dom', series: [{ key: 'crypto.btc_dominance', role: 'focal' }], desc: 'BTC 主导率', yFmt: x => fmtNum(x, 1) + '%' })}</div>`;
  }
  if (tab === 'geo') {
    const hs = ST.hotspots || [];
    h += `<h2>七大热点 <span class="count">${hs.length}</span><span class="take">浅色 = 12 个月概率区间，深色 = 5 年；预测市场为实时</span></h2><div class="grid g-3">${hs.map(x => { const pm = x.pm_key ? v('pm.' + x.pm_key) : null; const bar = (r, c) => r ? `<div style="height:8px;background:var(--surface-3);border-radius:4px;position:relative"><i style="position:absolute;top:0;bottom:0;left:${r[0]}%;width:${Math.max(1, r[1] - r[0])}%;background:${c};border-radius:4px"></i></div>` : ''; return `<div class="card"><b>${esc(x.name)}</b><div class="small" style="margin-top:6px">12 个月 ${x.p12 ? x.p12.join('–') + '%' : '—'} <span class="muted">${esc(x.p12_type || '')}</span></div>${bar(x.p12, 'var(--c2)')}<div class="small" style="margin-top:6px">5 年 ${x.p5 ? x.p5.join('–') + '%' : '—'} <span class="muted">${esc(x.p5_type || '')}</span></div>${bar(x.p5, 'var(--c1)')}${pm != null ? `<div class="small" style="margin-top:6px" data-metric="pm.${esc(x.pm_key)}">预测市场 <b class="mono">${fmtNum(pm, 1)}%</b> <span class="muted">${esc(meta('pm.' + x.pm_key).label || '')}</span></div>` : ''}<div class="small muted" style="margin-top:6px">锚点：${esc(x.anchor || '')}</div><div class="small" style="margin-top:4px">领先指标：${esc(x.trigger || '')}</div></div>`; }).join('')}</div>`;
    h += `<h2>物理通道 <span class="take">IMF PortWatch 7 日均 / 战前基线 · 解放军台海活动 · GPR</span></h2><div class="grid g-kpi">${[['hormuz', '霍尔木兹'], ['bab_el_mandeb', '曼德海峡'], ['suez', '苏伊士'], ['taiwan', '台湾海峡'], ['malacca', '马六甲']].map(([k, lab]) => M['chokepoint.' + k + '.ratio'] ? tile({ label: lab + ' 通行/基线', key: 'chokepoint.' + k + '.ratio', fmt: 'pct', spark: 'chokepoint.' + k + '.transits', sub: `7日均 ${fmtNum(v('chokepoint.' + k + '.avg7'), 1)} · 基线 ${fmtNum(v('chokepoint.' + k + '.baseline'), 0)} 艘/日` }) : '').join('')}${tile({ label: 'PLA 台海军机/日', key: 'pla.aircraft_daily', fmt: 'num', d: 0, spark: 'pla.aircraft_daily', sub: `7日均 ${fmtNum(v('pla.aircraft_7d_avg'), 0)} · 30日最高 ${fmtNum(v('pla.aircraft_30d_max'), 0)} · >60 演习级` })}${tile({ label: 'GPR 地缘风险', key: 'gpr.daily', fmt: 'num', d: 0, spark: 'gpr.daily', sub: `30日均 ${fmtNum(v('gpr.daily_30d_avg'), 0)}（>200 高位）` })}${tile({ label: '布伦特期现价差', key: 'war.brent_physical_premium', fmt: 'num', d: 1, prefix: '$', sub: 'EIA 现货 − 期货；>15 实物中断' })}${tile({ label: 'SCFI 集运', key: 'freight.scfi', fmt: 'num', d: 0, sub: '上海航交所' })}${tile({ label: '铀期货', key: 'px.URANIUM_FUT', prefix: '$', fmt: 'num', d: 1, spark: 'px.URANIUM_FUT', sub: '/lb · 报告现货 ~$90' })}</div>`;
    h += `<h2>资产雷达 <span class="take">先问哪条物理通道会被切断、多久，再问谁会赢</span></h2>${watchTable(['能源与航运', '避险与利率', '军工', '亚洲市场', '铀矿物化肥'])}`;
    h += `<h2>走势</h2><div class="grid g-2">${chartCard({ id: 'g-brent', series: [{ key: 'px.BRENT', label: '布伦特期货', role: 'focal' }, { key: 'eia.brent_spot', label: 'EIA 现货' }], thresholds: [{ value: 72.48, label: '战前 $72.5' }, { value: 126, label: '4月峰 $126' }], desc: '期货与实物现货；价差 = 物理中断溢价', yFmt: x => '$' + fmtNum(x, 0) })}${chartCard({ id: 'g-gold', series: [{ key: 'px.GOLD', label: '黄金期货', role: 'focal' }, { key: 'lbma.gold_pm', label: 'LBMA PM' }], thresholds: [{ value: 5608, label: 'ATH $5,608' }, { value: 5608 * 0.75, label: '−25%' }], desc: '黄金：报告称真正对冲的是利率与美元', yFmt: x => '$' + fmtPx(x) })}${chartCard({ id: 'g-us10y', series: [{ key: 'px.US10Y', label: '10Y', role: 'focal' }, { key: 'ust.real10y', label: '实际收益率' }], thresholds: [{ value: 5, label: '5%' }, { value: 4, label: '4%' }], desc: '名义与实际 10 年期', yFmt: pctF })}${chartCard({ id: 'g-choke', series: [{ key: 'chokepoint.hormuz.transits', label: '霍尔木兹', role: 'focal' }, { key: 'chokepoint.bab_el_mandeb.transits', label: '曼德' }, { key: 'chokepoint.taiwan.transits', label: '台海' }], desc: '咽喉要道日通过量（艘/日，IMF PortWatch，约 7 天滞后）', yFmt: x => fmtNum(x, 0) })}${chartCard({ id: 'g-rhm', series: [{ key: 'px.RHM', role: 'focal' }], thresholds: [{ value: 2007, label: '€2,007' }, { value: 2007 * 0.55, label: '−45%' }], desc: '莱茵金属：预算涨、股价跌的背离', yFmt: x => '€' + fmtPx(x) })}${chartCard({ id: 'g-asia', series: [{ key: 'px.TAIEX', label: '台股', role: 'focal', transform: idx }, { key: 'px.KOSPI', label: 'KOSPI', transform: idx }, { key: 'px.TSMC_TW', label: '台积电', transform: idx }], thresholds: [{ value: 100, label: '基期' }], desc: '指数化 = 100（同一起点）', yFmt: x => fmtNum(x, 0), range: '1Y' })}${chartCard({ id: 'g-pm', series: [{ key: 'pm.taiwan_clash_2027', label: '台海冲突', role: 'focal' }, { key: 'pm.ukraine_ceasefire', label: '俄乌停火' }, { key: 'pm.iran_israel_ceasefire', label: '以伊停火维持' }], area: true, min: 0, max: 100, desc: 'Polymarket 概率（%）', yFmt: x => fmtNum(x, 0) + '%' })}${chartCard({ id: 'g-pla', series: [{ key: 'pla.aircraft_daily', label: 'PLA 军机/日', role: 'focal' }], thresholds: [{ value: 60, label: '60 架次' }], desc: '解放军台海周边军机架次（plavis 社区整理）', yFmt: x => fmtNum(x, 0) })}${chartCard({ id: 'g-gpr', series: [{ key: 'gpr.daily', label: 'GPR', role: 'focal' }], thresholds: [{ value: 200, label: '200' }], desc: 'Caldara–Iacoviello 地缘风险指数（日频）', yFmt: x => fmtNum(x, 0) })}${chartCard({ id: 'g-vix', series: [{ key: 'px.VIX', role: 'focal' }], thresholds: [{ value: 30, label: '30' }], desc: 'VIX；LPL：27 次事件平均 17.9 日见底', yFmt: x => fmtNum(x, 0) })}</div>`;
    const matTable = m => !m ? '' : `<div class="tbl"><table class="mat"><thead><tr>${m.heads.map(x => `<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${m.rows.map(r => `<tr><td><b>${esc(r.n)}</b></td>${r.c.map(c => { const i = c.indexOf(' '); const sym = i > 0 ? c.slice(0, i) : c; const rest = i > 0 ? c.slice(i + 1) : ''; const k = sym.startsWith('↑↑') ? 'u' : sym.startsWith('⚡') ? 'p' : sym.startsWith('↑') ? 'u' : sym.startsWith('↓') ? 'd' : 'n'; return `<td><span class="dir2 ${k}">${esc(sym)}</span> ${esc(rest)}</td>`; }).join('')}</tr>`).join('')}</tbody></table></div>`;
    h += `<details class="appendix"><summary>附录：情景 × 资产矩阵（表 A 商品/运力/货币 · 表 B 股票/数字资产）</summary><div class="body">${matTable(ST.matrix_a)}<div style="height:12px"></div>${matTable(ST.matrix_b)}</div></details>`;
    if (ST.start_table) h += `<details class="appendix"><summary>附录：报告起点表（2026-09 中旬）</summary><div class="body"><div class="tbl"><table><thead><tr><th>资产</th><th>报告水平</th><th>相对参照</th><th>含义</th></tr></thead><tbody>${ST.start_table.map(r => `<tr>${r.map(c => `<td class="small">${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div></details>`;
    if (ST.war_risks) h += `<details class="appendix"><summary>附录：八条纪律</summary><div class="body prose">${ST.war_risks.map(r => `<p><b>${esc(r[0])}</b><br><span class="ink2">${esc(r[1])}</span></p>`).join('')}</div></details>`;
  }
  if (tab === 'ai') {
    h += `<h2>四把尺子 <span class="take">估值 · 资本开支 · 融资结构 · 货币与 IPO</span></h2><div class="grid g-kpi">${tile({ label: 'CAPE（估值尺）', key: 'val.cape', fmt: 'num', d: 1, spark: 'val.cape', sub: '1999-12 约 44；仅次于互联网泡沫' })}${tile({ label: 'SPY−RSP 30日差', key: 'ai.breadth_gap_30d', fmt: 'num', d: 1, unit: 'pp', sub: '>5 = 集中度扩大' })}${tile({ label: 'NVDA 较52周高', key: 'dd52w.NVDA', fmt: 'pct', spark: 'px.NVDA', sub: '−20% 前兆 · −30% 情景' })}${tile({ label: 'SOXX 较52周高', key: 'dd52w.SOXX', fmt: 'pct', spark: 'px.SOXX', sub: '≥30% 回撤 = 阶段一情景' })}${tile({ label: '高收益利差（融资尺）', key: 'fred.HY_OAS', fmt: 'num', d: 2, unit: '%', spark: 'fred.HY_OAS', sub: '>5% 信用重定价；FRED 本机不可达' })}${tile({ label: '联邦基金上限', key: 'fed.target_high', fmt: 'num', d: 2, unit: '%', sub: '加息周期与 1999-06→2000-05 同构' })}${tile({ label: 'Anthropic 年内 IPO', key: 'pm.anthropic_ipo', fmt: 'num', d: 0, unit: '%', spark: 'pm.anthropic_ipo', sub: '报告约 70%；11 月挂牌' })}${tile({ label: 'CoreWeave 较52周高', key: 'dd52w.CRWV', fmt: 'pct', spark: 'px.CRWV', sub: '新云信用事件前兆' })}${tile({ label: 'GE Vernova', key: 'px.GEV', delta: 'chg30d.GEV', deltaLabel: '30d', spark: 'px.GEV', prefix: '$', sub: `较52周高 ${fmtPct(v('dd52w.GEV'))}` })}${tile({ label: 'IPO ETF 较52周高', key: 'dd52w.IPO_ETF', fmt: 'pct', spark: 'px.IPO_ETF', sub: '零售准入后的基准' })}${tile({ label: 'Circle 较52周高', key: 'dd52w.CRCL', fmt: 'pct', spark: 'px.CRCL' })}${tile({ label: 'KOSPI 较52周高', key: 'dd52w.KOSPI', fmt: 'pct', spark: 'px.KOSPI', sub: '海力士 ' + fmtPct(v('dd52w.SKHYNIX')) })}</div>`;
    if (ST.ai_phases) h += `<h2>两段式机会分布 <span class="count">报告主观概率</span></h2><div class="grid g-3">${ST.ai_phases.map((p, i) => `<div class="card"><b>${esc(p.title)}</b><div class="small ink2" style="margin:6px 0">${esc(p.desc)}</div><ul class="small" style="margin:0;padding-left:16px">${(p.items || []).map(x => `<li>${esc(x)}</li>`).join('')}</ul></div>`).join('')}</div>`;
    h += `<h2>卖铲人与瓶颈层</h2>${watchTable(['半导体', '云与新云', '电力设备', '加密相关股', '美股指数'])}`;
    h += `<h2>走势</h2><div class="grid g-2">${chartCard({ id: 'a-nvda', series: [{ key: 'px.NVDA', label: 'NVDA', role: 'focal', transform: idx }, { key: 'px.SOXX', label: 'SOXX', transform: idx }, { key: 'px.NDX', label: 'NDX', transform: idx }], thresholds: [{ value: 100, label: '基期' }], desc: '指数化 = 100', yFmt: x => fmtNum(x, 0), range: '1Y' })}${chartCard({ id: 'a-breadth', series: [{ key: 'px.SPY', label: 'SPY', role: 'focal', transform: idx }, { key: 'px.RSP', label: 'RSP 等权', transform: idx }], thresholds: [{ value: 100, label: '基期' }], desc: '市值加权 vs 等权（集中度）', yFmt: x => fmtNum(x, 0), range: '1Y' })}${chartCard({ id: 'a-credit', series: [{ key: 'fred.HY_OAS', label: 'HY OAS', role: 'focal' }, { key: 'fred.IG_OAS', label: 'IG OAS' }], thresholds: [{ value: 5, label: '5%' }], desc: '信用利差（FRED；云端运行器可达）', yFmt: pctF })}${chartCard({ id: 'a-power', series: [{ key: 'px.GEV', label: 'GEV', role: 'focal', transform: idx }, { key: 'px.VRT', label: 'VRT', transform: idx }, { key: 'px.SIEMENS_ENERGY', label: '西门子能源', transform: idx }], thresholds: [{ value: 100, label: '基期' }], desc: '电力设备（指数化）', yFmt: x => fmtNum(x, 0), range: '1Y' })}${chartCard({ id: 'a-neo', series: [{ key: 'px.CRWV', label: 'CRWV', role: 'focal', transform: idx }, { key: 'px.WULF', label: 'WULF', transform: idx }, { key: 'px.IREN', label: 'IREN', transform: idx }], thresholds: [{ value: 100, label: '基期' }], desc: '新云与矿企转型（指数化）', yFmt: x => fmtNum(x, 0), range: '1Y' })}${chartCard({ id: 'a-korea', series: [{ key: 'px.KOSPI', label: 'KOSPI', role: 'focal', transform: idx }, { key: 'px.SKHYNIX', label: 'SK海力士', transform: idx }], thresholds: [{ value: 100, label: '基期' }], desc: '韩国：杠杆 ETF 爆仓模式', yFmt: x => fmtNum(x, 0), range: '1Y' })}</div>`;
    const thSet = new Set(['thailand_dc', 'sea_dc', 'power_grid', 'nuclear_smr']); const thc = clusters(n => (n.topics || []).some(t => thSet.has(t))).slice(0, 4);
    h += `<h2>读者主场：泰国 EEC 电网与东南亚数据中心 <span class="take">8.8 GW 采信 vs 35 GW 申请；瓶颈在输配电</span></h2><div class="grid g-2"><div class="card">${ST.eec ? `<div class="tbl" style="border:0"><table><thead><tr><th>交付点</th><th class="num">容量</th><th>状态/日期</th></tr></thead><tbody>${ST.eec.map(r => `<tr><td>${esc(r[0])}</td><td class="num">${esc(r[1])}</td><td class="small">${esc(r[2])}</td></tr>`).join('')}</tbody></table></div>` : ''}</div><div class="card">${thc.length ? thc.map(c => storyline(c, 3)).join('') : '<div class="empty">近 7 天无相关新闻</div>'}</div></div>`;
    if (ST.ai_paths) h += `<details class="appendix"><summary>附录：个人路径矩阵（报告）</summary><div class="body"><div class="tbl"><table><thead><tr><th>路径</th><th>门槛</th><th>上行</th><th>失败率/基准</th><th>适用性</th></tr></thead><tbody>${ST.ai_paths.map(r => `<tr>${r.map(c => `<td class="small">${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div></details>`;
  }
  h += sectionCal(rep) + sectionNews(rep, 6);
  el.innerHTML = h; initCharts(el);
}

function renderTrack() {
  const el = document.getElementById('tab-track'); let h = `<h2 style="margin-top:20px">三篇报告 <span class="count">基准日 2026-09-20</span><span class="take">把报告结论当作待验证的推演，逐日对照</span></h2><div class="grid g-3">${(D.reports || []).map((r, i) => `<div class="card"><div class="kicker">0${i + 1} · ${esc(r.date || '')}</div><b style="font-size:16px">${esc(r.title)}</b><div class="small ink2" style="margin:6px 0">${esc(String(r.thesis || '').split(/[。]/)[0])}。</div><div class="small muted">${esc(r.window || '')} · 约 20 分钟 · <a href="${esc(r.file)}" target="_blank">原报告 ↗</a></div></div>`).join('')}</div>`;
  h += `<h2>逻辑链实况 <span class="count">3 条主线</span></h2>${['crypto', 'war', 'ai'].map(k => `<h3>${esc(CHAINS[k] ? CHAINS[k].title : k)}</h3>${stepper(k)}`).join('')}`;
  const rows = [...BASE].sort((a, b) => Math.abs(b.change_pct != null ? b.change_pct : (b.change_pts || 0)) - Math.abs(a.change_pct != null ? a.change_pct : (a.change_pts || 0)));
  h += `<h2>基线 vs 现在 <span class="count">${BASE.length} 项</span><span class="take">偏离最大的排前</span></h2><div class="tbl"><table><thead><tr><th>报告</th><th class="first">指标</th><th class="num">报告基线</th><th class="num">现在</th><th class="num">变化</th><th class="pri2">说明</th></tr></thead><tbody>${rows.map(b => { const chg = b.change_pts != null ? `<span class="${cls(b.change_pts)}">${(b.change_pts > 0 ? '+' : '') + neg(b.change_pts.toFixed(2))} pp</span>` : (b.change_pct == null ? '—' : dirHtml(b.change_pct)); const bar = b.change_pct != null ? `<span class="cbar" style="width:80px;color:${b.change_pct >= 0 ? 'var(--up)' : 'var(--down)'}"><span class="fill fired" style="left:${b.change_pct >= 0 ? 50 : 50 - Math.min(50, Math.abs(b.change_pct))}%;width:${Math.min(50, Math.abs(b.change_pct))}%"></span><span class="th" style="left:50%"></span></span>` : ''; return `<tr data-metric="${esc(b.metric || '')}"><td>${repChip(b.report)}</td><td class="first">${esc(b.label)}<span class="ticker">${esc(b.metric || '')}</span></td><td class="num">${esc(b.baseline_display || fmtPx(b.baseline_value))}<span class="ticker">${esc(b.baseline_date || '')}</span></td><td class="num">${b.now == null ? '<span class="muted">无数据</span>' : (b.fmt === 'pct' ? fmtPct(b.now) : (b.fmt === 'num' ? fmtNum(b.now, 2) : fmtPx(b.now)))}<span class="ticker">${esc(b.now_date || '')}</span></td><td class="num">${chg} ${bar}</td><td class="small muted pri2">${esc(b.note || '')}</td></tr>`; }).join('')}</tbody></table></div>`;
  const byDate = {}; HIST.forEach(a => (byDate[a.date] = byDate[a.date] || []).push(a)); const dates = Object.keys(byDate).sort().reverse();
  h += `<h2>推演变化日志 <span class="count">${dates.length} 天</span><span class="take">每日触发与解除（最近 120 天）</span></h2><div class="card log">${dates.slice(0, 60).map((d, i) => { const cur = new Set(byDate[d].map(a => a.rule_id)); const prev = i + 1 < dates.length ? new Set(byDate[dates[i + 1]].map(a => a.rule_id)) : new Set(); const on = byDate[d].filter(a => !prev.has(a.rule_id)); const off = [...prev].filter(id => !cur.has(id)); return `<div class="day">${d}</div>${on.map(a => `<div class="en" data-rule="${esc(a.rule_id)}"><span class="w on">触发</span><span>${lvlChip(a.level)} ${esc(a.title)}</span></div>`).join('')}${off.map(id => { const r = RULES.find(x => x.rule_id === id); return `<div class="en" data-rule="${esc(id)}"><span class="w off">解除</span><span>${r ? lvlChip(r.level) + ' ' + esc(r.title) : esc(id)}</span></div>`; }).join('')}${!on.length && !off.length ? '<div class="en"><span class="w off">—</span><span class="muted">无变化（' + byDate[d].length + ' 条持续触发）</span></div>' : ''}`; }).join('')}</div>`;
  h += `<h2>完整触发日历 <span class="count">${CAL.filter(e => e.days_to >= -1).length} 项</span></h2><div class="card">${calRows()}</div>`;
  el.innerHTML = h; initCharts(el);
}

function renderRead() {
  const el = document.getElementById('tab-read'); const tc = D.topic_counts || {}; const density = LS('density_read') || 'scan';
  const pulse = Object.entries(tc).sort((a, b) => b[1]['24h'] - a[1]['24h']).slice(0, 12).map(([k, c]) => `<button class="pillbtn" data-topic="${esc(k)}" aria-pressed="false">${esc((TOPICS[k] || {}).label || k)} <b>${c['24h']}</b><span class="muted">/${c['48h']}</span></button>`).join('');
  const topicOpts = Object.entries(TOPICS).sort((a, b) => String(a[1].report).localeCompare(String(b[1].report))).map(([k, t]) => `<option value="${esc(k)}">${esc(rl(t.report))} · ${esc(t.label)}</option>`).join('');
  el.innerHTML = `<h2 style="margin-top:20px">阅读 <span class="count">${NEWS.length} 条 · 最近 7 天</span><span class="take">已读 <span id="read-n">${NEWS.filter(n => readSet.has(n.id)).length}</span>/${NEWS.length} · 无 LLM 改写，全部为原标题与摘要</span><span class="right"><span class="seg" id="density-seg"><button data-v="scan" aria-pressed="${density === 'scan'}">扫描</button><button data-v="summary" aria-pressed="${density === 'summary'}">摘要</button><button data-v="deep" aria-pressed="${density === 'deep'}">研读</button></span></span></h2>
  <div class="card"><div class="kicker" style="margin-bottom:6px">话题脉搏（24h 独立来源 / 48h）</div><div class="pills">${pulse}</div></div>
  <div class="filters"><label>报告 <select id="f-report"><option value="">全部</option><option value="crypto">加密</option><option value="war">地缘</option><option value="ai">AI 时代</option><option value="all">宏观</option></select></label><label>话题 <select id="f-topic"><option value="">全部</option>${topicOpts}</select></label><label>语言 <select id="f-lang"><option value="">全部</option><option value="zh">中文</option><option value="en">English</option></select></label><label><input type="checkbox" id="f-unread"> 只看未读</label><label><input type="checkbox" id="f-hot"> 只看敏感（权重≥3）</label><input type="search" id="f-q" placeholder="搜索标题/摘要…" style="min-width:200px"></div>
  <div class="read-grid"><div id="story-list"></div><aside class="river" id="river"><div class="kicker" style="margin-bottom:6px">最新 40 条</div></aside></div>`;
  const wrap = el.querySelector('.read-grid'); wrap.setAttribute('data-density', density);
  const apply = () => { const rep = el.querySelector('#f-report').value, tp = el.querySelector('#f-topic').value, lang = el.querySelector('#f-lang').value, unread = el.querySelector('#f-unread').checked, hot = el.querySelector('#f-hot').checked, q = el.querySelector('#f-q').value.trim().toLowerCase();
    const filt = n => (!rep || (n.topics || []).some(t => TOPICS[t] && TOPICS[t].report === rep)) && (!tp || (n.topics || []).includes(tp)) && (!lang || n.lang === lang) && (!unread || !readSet.has(n.id)) && (!hot || (n.topics || []).some(t => (TOPICS[t] || {}).weight >= 3)) && (!q || (n.title + ' ' + (n.summary || '')).toLowerCase().includes(q));
    const cs = clusters(filt); const list = el.querySelector('#story-list'); list.innerHTML = cs.length ? cs.slice(0, 12).map(c => storyline(c, 6)).join('') + (cs.length > 12 ? `<details><summary class="small muted" style="padding:8px 0;cursor:pointer">更多话题 (${cs.length - 12})</summary>${cs.slice(12).map(c => storyline(c, 6)).join('')}</details>` : '') : '<div class="empty">没有匹配的新闻</div>';
    const river = NEWS.filter(filt).slice(0, 40); el.querySelector('#river').innerHTML = `<div class="kicker" style="margin-bottom:6px">最新 ${river.length} 条</div>` + river.map(n => `<div class="it ${readSet.has(n.id) ? 'read' : ''}" data-id="${esc(n.id)}"><a href="${esc(n.link)}" target="_blank" rel="noopener">${esc(n.title)}</a><div class="meta">${esc(n.source)} · T${n.tier || '?'} · ${ageLabel(n.published || n.first_seen)}</div></div>`).join(''); };
  el.querySelectorAll('select,input').forEach(x => x.addEventListener('change', apply)); el.querySelector('#f-q').addEventListener('input', apply);
  el.querySelectorAll('.pillbtn[data-topic]').forEach(p => p.addEventListener('click', () => { const on = p.getAttribute('aria-pressed') === 'true'; el.querySelectorAll('.pillbtn[data-topic]').forEach(x => x.setAttribute('aria-pressed', 'false')); p.setAttribute('aria-pressed', String(!on)); el.querySelector('#f-topic').value = on ? '' : p.dataset.topic; apply(); }));
  el.querySelector('#density-seg').addEventListener('click', e => { const b = e.target.closest('button'); if (!b) return; LS('density_read', b.dataset.v); wrap.setAttribute('data-density', b.dataset.v); el.querySelectorAll('#density-seg button').forEach(x => x.setAttribute('aria-pressed', String(x === b))); });
  apply();
}

function renderData() {
  const el = document.getElementById('tab-data'); const run = D.run || {};
  let h = `<h2 style="margin-top:20px">抓取器状态 <span class="count">生成于 ${esc(D.generated_at)}</span><span class="take">总耗时 ${run.duration_s || '?'} s</span></h2><div class="tbl"><table><thead><tr><th>抓取器</th><th>状态</th><th class="num">指标</th><th class="num">回填</th><th class="num">新闻</th><th class="num">秒</th><th>备注</th></tr></thead><tbody>${Object.entries(run.fetchers || {}).map(([k, s]) => `<tr><td><b>${esc(k)}</b></td><td>${s.skipped ? '<span class="chip">未运行</span>' : (s.ok ? '<span class="chip state fired opportunity"><i class="dot"></i>正常</span>' : '<span class="chip state fired invalidation"><i class="dot"></i>失败</span>')}${s.stale_from ? `<div class="ticker">上次 ${esc(String(s.stale_from).slice(0, 16))}</div>` : ''}${s.resumed_from ? '<div class="ticker">断点续跑跳过</div>' : ''}</td><td class="num">${s.metrics ?? ''}</td><td class="num">${s.backfill ?? ''}</td><td class="num">${s.news ?? ''}</td><td class="num">${s.seconds ?? ''}</td><td class="small muted">${esc(s.error || s.notes || '')}</td></tr>`).join('')}</tbody></table></div>`;
  const sub = ((run.fetchers || {}).extras || {}).sub_status || {}; if (Object.keys(sub).length) h += `<h3>专项来源</h3><div class="card"><div class="chips">${Object.entries(sub).map(([k, s]) => `<span class="chip ${s.ok ? '' : 'lvl invalidation'}" title="${esc(s.error || '')}">${s.ok ? '✓' : '✕'} ${esc(k)}${s.n != null ? ' (' + s.n + ')' : ''}</span>`).join('')}</div></div>`;
  const fs = run.feed_status || {}; const fsE = Object.entries(fs); const okN = fsE.filter(([k, s]) => s.ok).length;
  h += `<h2>新闻源 <span class="count">${okN}/${fsE.length} 正常</span></h2><div class="tbl" style="max-height:50vh"><table><thead><tr><th class="first">来源</th><th>状态</th><th class="num">条数</th><th>错误</th></tr></thead><tbody>${fsE.sort((a, b) => (a[1].ok === b[1].ok ? 0 : (a[1].ok ? 1 : -1))).map(([k, s]) => `<tr><td class="first">${esc(k)}</td><td>${s.ok ? '<span class="up">✓</span>' : '<span class="down">✕</span>'}</td><td class="num">${s.n ?? ''}</td><td class="small muted">${esc(s.error || '')}</td></tr>`).join('')}</tbody></table></div>`;
  const stale = Object.entries(M).filter(([k]) => /^(px|pm|stable|fred|chokepoint)\./.test(k)).map(([k, m]) => ({ k, d: m.asof || m.date, age: daysBetween(String(m.asof || m.date || '').slice(0, 10), TODAY) })).filter(x => x.age != null && x.age > 3);
  h += `<h2>过期指标 <span class="count">${stale.length}</span><span class="take">超过 3 天未更新（周末/假日、PortWatch 7 天滞后属正常）</span></h2><div class="card small">${stale.length ? stale.map(x => `<span class="chip" data-metric="${esc(x.k)}" style="cursor:pointer">${esc(x.k)} ${esc(String(x.d).slice(0, 10))}</span>`).join(' ') : '<span class="muted">无</span>'}</div>`;
  h += `<h2>来源等级与准确性约定</h2><div class="card small prose"><p><b>T1</b> 官方/一手：美联储、财政部、SEC、交易所与协议链上数据、DefiLlama、Polymarket 成交价、IMF PortWatch。<b>T2</b> 主流媒体与成熟聚合：CoinDesk、The Block、CNBC、Google News 检索到的路透/彭博等。<b>T3</b> 二级聚合/博客：仅作线索，需二次核实。</p><p>价格交叉：BTC 用 CoinGecko + Binance；黄金用期货 + LBMA 定盘价；美债用 Yahoo + 财政部曲线；FRED 在本机不可达时以财政部曲线兜底并标注。所有指标带来源与时间戳；规则在数据缺失时显示"无数据"而不猜测。本工具不用大模型改写或总结任何内容；新闻排序可选用只输出概率的判断模型（Jev），未配置时纯关键词，规则判定永远与它无关。</p></div>`;
  if (ST.data_gaps) h += `<h2>报告自述的数据缺口</h2><div class="card small">${ST.data_gaps.map(g => `<p style="margin:4px 0">· ${esc(g)}</p>`).join('')}</div>`;
  const runs = D.runs || []; if (runs.length) h += `<h2>运行记录 <span class="count">${runs.length}</span></h2><div class="tbl"><table><thead><tr><th>时间</th><th class="num">耗时(s)</th><th>抓取器</th></tr></thead><tbody>${runs.slice(0, 15).map(r => `<tr><td class="mono small">${esc(r.run_at)}</td><td class="num">${fmtNum(r.duration_s, 0)}</td><td class="small">${Object.entries(r.status || {}).map(([k, s]) => `${k}:${s.skipped ? '跳过' : (s.ok ? '✓' : '✕')}`).join(' ')}</td></tr>`).join('')}</tbody></table></div>`;
  h += `<h2>指标字典 <span class="count">${Object.keys(M).length} 个键</span></h2><div class="filters"><input type="search" id="dict-q" placeholder="搜索键名…" style="min-width:240px"></div><div class="tbl" style="max-height:60vh" id="dict"></div>`;
  el.innerHTML = h;
  const dict = el.querySelector('#dict'); const drawDict = q => { const rows = Object.entries(M).filter(([k]) => !q || k.toLowerCase().includes(q)).sort().slice(0, 300); dict.innerHTML = `<table><thead><tr><th class="first">键</th><th class="num">值</th><th>日期</th><th>来源</th></tr></thead><tbody>${rows.map(([k, m]) => `<tr data-metric="${esc(k)}" style="cursor:pointer"><td class="first mono small">${esc(k)}</td><td class="num small">${m.value == null ? '—' : fmtPx(+m.value)}</td><td class="small mono">${esc(String(m.asof || m.date || '').slice(0, 10))}</td><td class="small muted">${esc(m.source || '')}</td></tr>`).join('')}</tbody></table>`; }; drawDict(''); el.querySelector('#dict-q').addEventListener('input', e => drawDict(e.target.value.trim().toLowerCase()));
}

// ---------- chrome: strip, rail foot, counts, watchstrip ----------
function renderChrome() {
  const run = D.run || {}; const fAll = Object.values(run.fetchers || {}).filter(f => !f.skipped); const ok = fAll.filter(f => f.ok === true).length; const degraded = fAll.filter(f => f.ok !== true).length;
  const gen = D.generated_at || ''; const ageH = (Date.now() - Date.parse(gen)) / 36e5; const stale = ageH > 26;
  document.getElementById('strip').innerHTML = `<span>数据截至 <span class="n ${stale ? 'stale' : ''}">${esc(gen.slice(0, 16).replace('T', ' '))}${stale ? ' 已过期' : ''}</span></span><span>·</span><span>抓取 <span class="n">${ok}/${fAll.length}</span> 正常</span>${degraded ? `<span>·</span><span class="chip" data-goto="data">降级 ${degraded}</span>` : ''}<span>·</span><span>规则 <span class="n">${RULES.length}</span> 已评估</span><span>·</span><span>新闻 <span class="n">${NEWS.length}</span> 条 / 7 天</span><span>·</span><span>触发 <span class="n">${fired.length}</span>（新 <span class="n">${fired.filter(r => r.is_new).length}</span>）</span>`;
  const counts = { overview: fired.filter(r => r.is_new).length ? `${fired.filter(r => r.is_new).length} 新` : '', crypto: `${byReport('crypto').filter(r => r.fired).length}`, geo: `${byReport('war').filter(r => r.fired).length}`, ai: `${byReport('ai').filter(r => r.fired).length}`, track: `${BASE.length}`, read: `${NEWS.length}`, data: `${ok}/${fAll.length}` };
  document.querySelectorAll('[data-count]').forEach(e => e.textContent = counts[e.dataset.count] || '');
  const nb = fired.filter(r => r.is_new).length; document.querySelectorAll('[data-badge="overview"]').forEach(e => { e.textContent = nb || ''; e.style.display = nb ? '' : 'none'; });
  document.getElementById('rail-foot').innerHTML = ['crypto', 'war', 'ai'].map(k => { const s = chainSummary(k); return s ? `<div class="st"><span>${esc(rl(k))}</span><span>${s.k}/${s.m}</span></div>` : ''; }).join('') + `<div style="margin-top:8px">数据日期 ${esc(TODAY)}</div>`;
  document.getElementById('watchstrip').innerHTML = [['BTC', 'px.BTC', 'chg24h.BTC'], ['布伦特', 'px.BRENT', 'chg1d.BRENT'], ['黄金', 'px.GOLD', 'chg1d.GOLD'], ['US10Y', 'px.US10Y', null]].map(([l, k, d]) => `<span data-metric="${k}">${l} <b>${k === 'px.US10Y' ? fmtNum(v(k), 2) + '%' : fmtPx(v(k))}</b> ${d ? dirHtml(v(d)) : ''}</span>`).join('');
}

// ---------- 简明模式（按顶尖金融分析网站 10 大核心功能重做） ----------
const MODE = { v: LS('mode') || 'simple' };
const GLOSS = [['BTC', '比特币'], ['ETH/BTC', '以太坊相对比特币'], ['ETH', '以太坊'], ['周线收于 50 周均线之上', '站上中期趋势线'], ['50 周均线', '中期趋势线'], ['200 周均线', '长期趋势线'], ['实现价格', '持有者平均成本'], ['ETF', '基金'], ['净流入', '资金流入'], ['净流出', '资金流出'], ['较 52 周高', '比一年高点'], ['较 1 年高点', '比一年高点'], ['较 ATH', '比历史高点'], ['较 6 个月高点', '比半年高点'], ['回撤', '下跌'], ['高收益债利差', '垃圾债借钱成本'], ['市值/年化收入', '市值除以年收入'], ['P/S', '市值/收入'], ['REV', '链上收入'], ['话题 24h 内 ≥', '今天有'], ['家来源', '家媒体在报道'], ['24h 内 ≥', '今天有'], ['预测市场', '赌盘'], ['Polymarket', '赌盘'], ['Kalshi', '赌盘']];
function plainOf(r) { if (r.plain) return r.plain; let t = r.title || ''; for (const [a, b] of GLOSS) t = t.split(a).join(b); return t; }
function fmtBig(x, unit) { if (x == null || isNaN(x)) return '—'; unit = unit || ''; const a = Math.abs(x); let s; if (a >= 1e12) s = neg((x / 1e12).toFixed(2)) + ' 万亿'; else if (a >= 1e8) s = neg((x / 1e8).toFixed(a >= 1e10 ? 0 : 1)) + ' 亿'; else if (a >= 1e4) s = neg((x / 1e4).toFixed(a >= 1e6 ? 0 : 2)) + ' 万'; else if (a >= 1000) s = neg(x.toFixed(0)); else if (a >= 100) s = neg(x.toFixed(1)); else if (a >= 1) s = neg(x.toFixed(2)); else s = neg(x.toFixed(4)); return unit + s; }
const pct0 = x => x == null ? '—' : neg((x > 0 ? '+' : '') + Math.round(x)) + '%';
