function alertsBlock(rep) { const rows = rep ? RULES.filter(r => r.report === rep || r.report === 'all') : RULES; const f = rows.filter(r => r.fired).sort((a, b) => ((b.is_new ? 1 : 0) - (a.is_new ? 1 : 0)) || (levelRank[a.level] - levelRank[b.level]) || a.priority - b.priority); const n = rows.filter(r => r._near).sort((a, b) => Math.abs(a._p.dist) - Math.abs(b._p.dist)); const newR = f.filter(r => r.is_new); const res = resolved.filter(r => !rep || r.report === rep || r.report === 'all'); const movers = [...YAHOO.map(y => ({ label: y.label, k: y.key, chg: v('chg1d.' + y.key) })), ...CRW.slice(0, 12).map(c => ({ label: c.symbol, k: c.symbol, chg: v('chg24h.' + c.symbol) }))].filter(x => x.chg != null).sort((a, b) => Math.abs(b.chg) - Math.abs(a.chg)).slice(0, 3);
  const chips = `<div class="chips" style="margin:6px 0 10px"><span class="chip">新触发 ${newR.length}</span><span class="chip">解除 ${res.length}</span>${movers.map(m => `<span class="chip">${esc(m.label)} ${fmtPct(m.chg)}</span>`).join('')}</div>`;
  const list = f.length + n.length ? `<div class="alist">${f.slice(0, 12).map(alertRow).join('')}${n.slice(0, 6).map(alertRow).join('')}</div>` : (() => { const nearest = rows.filter(r => !r.fired && r._p.dist != null).sort((a, b) => Math.abs(a._p.dist) - Math.abs(b._p.dist))[0]; return `<div class="empty big">今天 0 条触发。${nearest ? `离阈值最近：${esc(plainOf(nearest))}，${distText(nearest._p)}。` : ''}明早 6 点再查。</div>`; })();
  const tabs = rep ? '' : `<div class="pills" style="margin:8px 0">${['all', 'crypto', 'war', 'ai'].map(t => `<button class="pillbtn rt" data-rep="${t}" aria-pressed="${t === 'all'}">${t === 'all' ? '全部' : rl(t)}</button>`).join('')}</div>`;
  return `<div class="s-h">今日触发 <span class="count">${f.length}</span> · 接近 <span class="count">${n.length}</span> <span class="muted small">触发 ≠ 买卖建议</span><span class="right"><button class="pillbtn toggle-all">查看全部 ${rows.length} 条</button></span></div>${chips}${list}<div class="fullrules" style="display:none">${tabs}<div class="fr-body">${rulesTableFull(rows)}</div></div>`; }
// 催化剂日历
function impSquares(e) { const cat = e.category || ''; const n = /unlock|regulation|macro|election|halving/.test(cat) ? 3 : (/ipo|geopolitics|upgrade/.test(cat) ? 2 : 1); return `<span class="imp" title="重要度 ${n}/3">${'■'.repeat(n)}${'□'.repeat(3 - n)}</span>`; }
function linkedRules(e) { const a = new Set(e.assets || []); return RULES.filter(r => (r.assets || []).some(x => a.has(x)) || (r.when && r.when.type === 'date' && r.when.date === e.date)); }
function icsHref() { const dir = location.pathname.replace(/[^/]*$/, ''); return /github\.io$/.test(location.hostname) && /iPhone|iPad|Macintosh/.test(navigator.userAgent) ? 'webcal://' + location.host + dir + 'calendar.ics' : 'calendar.ics'; }
function calendarTabs(rep) { const src = CAL.filter(e => !rep || e.report === rep || e.report === 'all'); const buckets = { last: src.filter(e => e.days_to < 0 && e.days_to >= -7), week: src.filter(e => e.days_to >= 0 && e.days_to <= 6), next: src.filter(e => e.days_to >= 7 && e.days_to <= 13), later: src.filter(e => e.days_to >= 14 && e.days_to <= 90) }; const wd = d => ['日', '一', '二', '三', '四', '五', '六'][new Date(d + 'T00:00:00').getDay()]; const row = e => { const lr = linkedRules(e); return `<div class="crow" data-cal="${esc(e.date)}"><span class="cd">${esc(e.date.slice(5))}<span class="wk">周${wd(e.date)}</span></span><span class="cc ${e.days_to <= 7 && e.days_to >= 0 ? 'soon' : ''}">${e.days_to === 0 ? '今天' : (e.days_to > 0 ? e.days_to + ' 天后' : -e.days_to + ' 天前')}</span><span class="ce">${esc(e.title)}${e.approx ? ' <span class="muted">(约)</span>' : ''}</span>${impSquares(e)}<span class="cl">${repChip(e.report)}${lr.length ? `<span class="chip">${lr.length} 条规则</span>` : ''}</span>${e.note ? `<div class="cn">${esc(String(e.note).slice(0, 60))}</div>` : ''}</div>`; }; const def = buckets.week.length ? 'week' : (buckets.next.length ? 'next' : 'later'); return `<div class="s-h">催化剂日历 <span class="count">本周 ${buckets.week.length} · 下周 ${buckets.next.length}</span><span class="help" tabindex="0" role="note" aria-label="■ 越多越重要。「N 条规则」= 这件事影响几条判断。" data-tip="■ 越多越重要。「N 条规则」= 这件事影响几条判断。">?</span><span class="right"><a class="pillbtn" href="${icsHref()}" title="iPhone：点开选「订阅」；安卓/电脑：下载后用日历 App 打开导入。关键日子前一天提醒">加到手机日历</a></span></div><div class="card cal"><div class="pills" style="margin-bottom:8px">${[['last', '上周'], ['week', '本周'], ['next', '下周'], ['later', '之后 90 天']].map(([k, l]) => `<button class="pillbtn ct" data-b="${k}" aria-pressed="${k === def}">${l} <b>${buckets[k].length}</b></button>`).join('')}</div>${Object.entries(buckets).map(([k, arr]) => `<div class="cb" data-b="${k}" style="display:${k === def ? 'block' : 'none'}">${arr.length ? arr.map(row).join('') : '<div class="empty">没有</div>'}</div>`).join('')}</div>`; }
// 新闻
function newsTabs(rep) { const firedTopics = new Set(RULES.filter(r => r.fired && r.when && r.when.type === 'news').map(r => r.when.topic)); const cut = Date.now() - 48 * 36e5; const base = NEWS.filter(n => (n.tier || 3) <= 2 && Date.parse(n.published || n.first_seen || 0) >= cut); const forRep = t => base.filter(n => t === 'all' || (n.topics || []).some(x => TOPICS[x] && TOPICS[x].report === t)); const tabsList = rep ? [rep] : ['all', 'crypto', 'war', 'ai']; const row = n => { const pinned = (n.topics || []).some(t => firedTopics.has(t)); return `<div class="nrow ${readSet.has(n.id) ? 'read' : ''} ${pinned ? 'pin' : ''}" data-id="${esc(n.id)}"><span class="nt">${ageLabel(n.published || n.first_seen)}</span><a href="${esc(n.link)}" target="_blank" rel="noopener">${esc(n.title)}</a><span class="nm">${esc(n.source)} <span class="chip tier">T${n.tier || '?'}</span>${(n.topics || []).slice(0, 2).map(t => `<span class="chip">${esc((TOPICS[t] || {}).label || t)}</span>`).join('')}${pinned ? '<span class="chip lvl warning">关联触发规则</span>' : ''}</span></div>`; }; const jb = n => (n.jev_score != null && n.jev_score >= 0.5) ? 1 : 0; const body = t => { const items = forRep(t).sort((a, b) => { const pa = (a.topics || []).some(x => firedTopics.has(x)) ? 1 : 0, pb = (b.topics || []).some(x => firedTopics.has(x)) ? 1 : 0; return pb - pa || jb(b) - jb(a) || Date.parse(b.published || b.first_seen || 0) - Date.parse(a.published || a.first_seen || 0); }); return `<div class="nb" data-t="${t}" style="display:${t === tabsList[0] ? 'block' : 'none'}">${items.length ? items.slice(0, 10).map(row).join('') + (items.length > 10 ? `<div class="more" style="display:none">${items.slice(10, 40).map(row).join('')}</div><button class="pillbtn nmore" style="margin-top:8px">加载更多（${Math.min(30, items.length - 10)}）</button>` : '') : '<div class="empty">48 小时内没有一二级来源的报道</div>'}</div>`; }; return `<div class="s-h">相关新闻 <span class="count">48 小时 · 一二级来源</span><span class="right"><a href="#read" data-goto="read">全部 ${NEWS.length} 条 →</a></span></div><div class="card news2">${rep ? '' : `<div class="pills" style="margin-bottom:8px">${tabsList.map(t => `<button class="pillbtn nt2" data-t="${t}" aria-pressed="${t === 'all'}">${t === 'all' ? '全部' : rl(t)}</button>`).join('')}</div>`}${tabsList.map(body).join('')}</div>`; }
// 故事图
function storyTitle(rep) { if (rep === 'crypto') { const b = v('px.BTC'), w = v('crypto.btc.wma50'); return b && w ? (b > w ? `比特币 $${fmtBig(b)} 站在中期趋势线之上，高出 ${Math.round((b / w - 1) * 100)}%` : `比特币 $${fmtBig(b)} 在中期趋势线之下，还差 ${Math.round((w / b - 1) * 100)}% 才到买入线`) : '比特币与趋势线'; } if (rep === 'war') { const r = v('chokepoint.hormuz.ratio'); return r != null ? `霍尔木兹海峡每天只有 ${fmtNum(v('chokepoint.hormuz.avg7'), 0)} 艘船通过，只有战前的 ${Math.round(r * 100)}%` : '霍尔木兹海峡船流'; } const dd = v('dd52w.SOXX'); return dd != null ? `半导体板块比一年高点低 ${Math.abs(Math.round(dd))}%，离报告说的 30% 大回撤还差 ${Math.max(0, 30 - Math.abs(Math.round(dd)))} 个百分点` : 'AI 核心资产'; }
