// 基线定位
function rangeBar(k, baseVal, cur) { const s = S[k] || []; if (s.length < 10 || cur == null) return ''; const vals = s.map(p => p[1]); let mn = Infinity, mx = -Infinity, mnD = '', mxD = ''; s.forEach(p => { if (p[1] < mn) { mn = p[1]; mnD = p[0]; } if (p[1] > mx) { mx = p[1]; mxD = p[0]; } }); if (mx === mn) return ''; const pos = x => Math.max(0, Math.min(100, (x - mn) / (mx - mn) * 100)); const pct = Math.round(vals.filter(x => x <= cur).length / vals.length * 100); return `<div class="rb"><div class="rbar"><i class="cur" style="left:${pos(cur)}%"></i>${baseVal != null ? `<i class="base" style="left:${pos(baseVal)}%"></i>` : ''}</div><div class="rl"><span>${fmtBig(mn)}<br><span class="muted">${mnD.slice(2)}</span></span><span class="muted">2 年区间 · 现在处于第 ${pct} 百分位</span><span style="text-align:right">${fmtBig(mx)}<br><span class="muted">${mxD.slice(2)}</span></span></div></div>`; }
function baselineList(rep, limit) { const rows = BASE.filter(b => (!rep || b.report === rep) && b.now != null).sort((a, b) => Math.abs(b.change_pct != null ? b.change_pct : (b.change_pts || 0)) - Math.abs(a.change_pct != null ? a.change_pct : (a.change_pts || 0))).slice(0, limit || 100); return `<div class="s-h">这个数字算高吗 <span class="count">报告基线 ▽ vs 现在 ▲</span></div><div class="card">${rows.map(b => { const chg = b.change_pts != null ? `${b.change_pts > 0 ? '升' : '降'} ${neg(Math.abs(b.change_pts).toFixed(1))}${b.fmt === 'pct' ? ' 个百分点' : ''}` : (b.change_pct == null ? '' : `${b.change_pct >= 0 ? '涨' : '跌'} ${Math.abs(b.change_pct).toFixed(0)}%`); return `<div class="brow" data-metric="${esc(b.metric || '')}"><div class="bh"><span class="bl">${esc(b.label)}</span><span class="bv">报告时 ${esc(b.baseline_display || fmtPx(b.baseline_value))} → 现在 <b>${b.fmt === 'pct' ? fmtPct(b.now) : (b.fmt === 'num' ? fmtNum(b.now, 2) : fmtBig(b.now))}</b> <span class="${cls(b.change_pct != null ? b.change_pct : b.change_pts)}">${chg}</span></span></div>${rangeBar(b.metric, b.fmt === 'pct' || b.fmt === 'num' ? b.baseline_value : b.baseline_value, b.now)}${b.note ? `<div class="bn">${esc(b.note)}</div>` : ''}</div>`; }).join('')}</div>`; }
// 热力图 + 异动
function marketMapBlock() { const items = [...YAHOO.filter(y => v('px.' + y.key) != null).map(y => ({ name: y.label.replace(/（.*?）|\(.*?\)/g, ''), g: y.group, k: y.key, chg: v('chg1d.' + y.key), size: IMPORTANCE[y.key] || 1, px: v('px.' + y.key), metric: 'px.' + y.key })), ...CRW.filter(c => v('px.' + c.symbol) != null && ['核心', '卫星'].includes(c.tier)).map(c => ({ name: c.symbol, g: '加密', k: c.symbol, chg: v('chg24h.' + c.symbol), size: IMPORTANCE[c.symbol] || 1, px: v('px.' + c.symbol), metric: 'px.' + c.symbol }))]; const movers = items.filter(x => x.chg != null).sort((a, b) => Math.abs(b.chg) - Math.abs(a.chg)).slice(0, 10); window.__MAP_ITEMS = items; return `<div class="s-h">全市场一图 <span class="count">${items.length} 个标的 · 颜色 = 今日涨跌</span></div><div class="grid" style="grid-template-columns:2fr 1fr"><div class="card" style="padding:8px"><div id="market-map" style="height:360px"></div></div><div class="card"><div class="kicker" style="margin-bottom:6px">今日异动前十</div>${movers.map(m => `<div class="mrow" data-metric="${esc(m.metric)}"><span>${esc(m.name)}</span><span class="muted small">${esc(m.g)}</span><span class="num ${cls(m.chg)}">${fmtPct(m.chg)}</span></div>`).join('')}</div></div>`; }
function initMarketMap() { const el = document.getElementById('market-map'); if (!el || !window.echarts || el.dataset.done) return; el.dataset.done = '1'; const items = window.__MAP_ITEMS || []; const groups = {}; items.forEach(it => (groups[it.g] = groups[it.g] || []).push(it)); const up = cssVar('--up'), down = cssVar('--down'), neutral = cssVar('--surface-3'); const col = c => { if (c == null || Math.abs(c) < 0.3) return neutral; const t = Math.min(1, Math.abs(c) / 5); const base = c > 0 ? up : down; return base + Math.round(60 + t * 160).toString(16).padStart(2, '0'); }; const data = Object.entries(groups).map(([g, arr]) => ({ name: g, children: arr.map(it => ({ name: it.name, value: it.size, chg: it.chg, metric: it.metric, itemStyle: { color: col(it.chg) }, label: { formatter: `${it.name}\n${fmtPct(it.chg)}` } })) })); const ch = echarts.init(el); instances.push(ch); ch.setOption({ animation: false, tooltip: { formatter: p => p.data.metric ? `${esc(p.name)}<br>今日 ${fmtPct(p.data.chg)}` : esc(p.name), backgroundColor: cssVar('--surface'), borderColor: cssVar('--grid'), textStyle: { color: cssVar('--ink'), fontSize: 12 } }, series: [{ type: 'treemap', roam: false, nodeClick: false, breadcrumb: { show: false }, leafDepth: null, squareRatio: 1, itemStyle: { borderColor: cssVar('--surface'), borderWidth: 2, gapWidth: 2 }, upperLabel: { show: true, height: 20, color: cssVar('--ink-2'), fontSize: 11 }, label: { color: cssVar('--ink'), fontSize: 11, overflow: 'truncate' }, levels: [{ itemStyle: { borderColor: cssVar('--page'), borderWidth: 3, gapWidth: 3 } }, { colorSaturation: [0.3, 0.6] }], data }] }); ch.on('click', p => { if (p.data && p.data.metric) openMetric(p.data.metric); }); }
