function buildSearch() { const box = document.getElementById('search'); if (!box) return; const list = document.getElementById('search-results'); const index = [...YAHOO.map(y => ({ t: 'asset', label: y.label + ' ' + y.symbol, k: 'px.' + y.key })), ...CRW.map(c => ({ t: 'asset', label: c.symbol + ' ' + (meta('px.' + c.symbol).name || ''), k: 'px.' + c.symbol })), ...RULES.map(r => ({ t: 'rule', label: plainOf(r) + ' ' + r.title, id: r.rule_id })), ...Object.keys(DEFS).map(k => ({ t: 'metric', label: DEFS[k] + ' ' + k, k }))]; const run = () => { const q = box.value.trim().toLowerCase(); if (!q) { list.dataset.open = 'false'; return; } const hits = index.filter(x => x.label.toLowerCase().includes(q)).slice(0, 8); const news = NEWS.filter(n => n.title.toLowerCase().includes(q)).slice(0, 4); list.innerHTML = hits.map(h => `<div class="sr" data-${h.t === 'rule' ? 'rule' : 'metric'}="${esc(h.t === 'rule' ? h.id : h.k)}"><span class="chip">${h.t === 'rule' ? '规则' : (h.t === 'asset' ? '资产' : '指标')}</span> ${esc(h.label.slice(0, 60))}</div>`).join('') + news.map(n => `<div class="sr" data-id="${esc(n.id)}"><span class="chip">新闻</span> <a href="${esc(n.link)}" target="_blank" rel="noopener">${esc(n.title.slice(0, 70))}</a></div>`).join('') || '<div class="sr muted">没有结果</div>'; list.dataset.open = 'true'; }; box.addEventListener('input', run); box.addEventListener('focus', run); document.addEventListener('keydown', e => { if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k') { e.preventDefault(); box.focus(); box.select(); } if (e.key === 'Escape') list.dataset.open = 'false'; }); document.addEventListener('click', e => { if (!e.target.closest('#search-wrap')) list.dataset.open = 'false'; else if (e.target.closest('.sr')) setTimeout(() => list.dataset.open = 'false', 50); }); }
